        "focus": "धातु-फाइबर प्रबलित तकनीक का उपयोग करके PA पर आधारित स्थैतिक विघटनकारी सामग्री। अनुप्रयोग दिशाओं में मोटर वाहन भागों, खनन उपकरण, बिजली उपकरण, कंटेनर, छड़, चादरें, विद्युत आवास, टयूबिंग, औद्योगिक कैस्टर, मोनोफिलामेंट्स और स्टाइलस शामिल हैं; ग्रेड और तैयार भाग के लिए प्रतिरोध और प्रसंस्करण की स्थिति को मान्य करें।",
