        "focus": "PA पर आधारित संवाहक सामग्री, कार्बन-फाइबर सुदृढ तकनीक का उपयोग करते हुए। अनुप्रयोग दिशाएँ शामिल हैं: ऑटोमोटिव पार्ट्स, खनन उपकरण, पावर टूल्स, कंटेनर, रॉड, शीट्स, इलेक्ट्रिकल हाउसिंग्स, ट्यूबिंग, औद्योगिक कैस्टर्स, मोनोफिलामेंट और स्टाइलस; ग्रेड और तैयार हिस्से के लिए प्रतिरोध और प्रक्रिया की स्थितियों को सत्यापित करें।",
        "process": "ग्रेड के लिए सुखाने, पिघलने के तापमान, मोल्ड तापमान और निवास के समय की पुष्टि करें; परीक्षणों के बाद प्रतिरोध, उपस्थिति और आयामों की जाँच करें।",
