      "profile": {
        "parts": "एटीएम और बैंकनोट-हैंडलिंग उपकरण, कॉपियर पेपर-संपर्क भागों, ऑटोमोटिव पार्ट्स, छड़, चादरें, गियर, बीयरिंग और विद्युत घटक",
        "focus": "धातु-फाइबर प्रबलित तकनीक का उपयोग करके POM पर आधारित स्थैतिक विघटनकारी सामग्री। अनुप्रयोग निर्देशों में एटीएम और बैंकनोट-हैंडलिंग उपकरण, कॉपियर पेपर-संपर्क भागों, मोटर वाहन भागों, छड़, चादरें, गियर, बीयरिंग और विद्युत घटक शामिल हैं; ग्रेड और तैयार भाग के लिए प्रतिरोध और प्रसंस्करण की स्थिति को मान्य करें।",
        "process": "ग्रेड के लिए सुखाने, पिघलने के तापमान, मोल्ड तापमान और निवास के समय की पुष्टि करें; परीक्षणों के बाद प्रतिरोध, उपस्थिति और आयामों की जाँच करें।",
        "reinforcement": "धातु-फाइबर प्रबलित; ग्रेड के लिए सुदृढीकरण सामग्री और निर्माण की पुष्टि करें",
        "tests": [
          "प्रतिरोध: इलेक्ट्रोड, परीक्षण वोल्टेज, नमूना स्थिति, तापमान और आर्द्रता को परिभाषित करें; सामग्री के नमूनों और ढाले हुए भागों दोनों का परीक्षण करें",
          "दीर्घकालिक व्यवहार: कंडीशनिंग, सफाई, घर्षण और उम्र बढ़ने के बाद स्थैतिक नियंत्रण का मूल्यांकन करें",
          "भाग सत्यापन: इच्छित अनुप्रयोग में दीवार की मोटाई, फाइबर अभिविन्यास, असेंबली और ग्राउंडिंग का आकलन करें"
        ]
      },
