      "profile": {
        "parts": "चिमटी, फोन और कैमरा हाउसिंग, उपकरण हाउसिंग, चिप ट्रे, इलेक्ट्रॉनिक घटक, पैकेजिंग शीट और इलेक्ट्रॉनिक पार्ट्स",
        "focus": "PC आधारित स्थायी एंटिस्टैटिक सामग्री, पॉलीमेरिक एंटिस्टैटिक संशोधन प्रौद्योगिकी का उपयोग करके। अनुप्रयोग दिशा में पिनसेट, फोन और कैमरा आवास, उपकरण आवास, चिप ट्रे, इलेक्ट्रॉनिक घटक, पैकेजिंग शीट और इलेक्ट्रॉनिक पार्ट्स शामिल हैं; ग्रेड और उत्तपन्न भाग के लिए प्रतिरोध और प्रसंस्करण शर्तों को सत्यापित करें।",
        "process": "ग्रेड के लिए सुखाने, पिघलने के तापमान, मोल्ड तापमान और निवास के समय की पुष्टि करें; परीक्षणों के बाद प्रतिरोध, उपस्थिति और आयामों की जाँच करें।",
        "reinforcement": "पॉलिमर एंटिस्टैटिक संशोधन; ग्रेड के लिए सुदृढीकरण सामग्री और सूत्र की पुष्टि करें",
        "tests": [
          "प्रतिरोध: इलेक्ट्रोड, परीक्षण वोल्टेज, नमूना स्थिति, तापमान और आर्द्रता को परिभाषित करें; सामग्री के नमूनों और ढाले हुए भागों दोनों का परीक्षण करें",
          "दीर्घकालिक व्यवहार: कंडीशनिंग, सफाई, घर्षण और उम्र बढ़ने के बाद स्थैतिक नियंत्रण का मूल्यांकन करें",
          "भाग सत्यापन: इच्छित अनुप्रयोग में दीवार की मोटाई, फाइबर अभिविन्यास, असेंबली और ग्राउंडिंग का आकलन करें"
        ]
      },
