      "profile": {
        "parts": "बोर्ड, शीट, वाहक टेप, प्रोफाइल, चिमटी, इलेक्ट्रॉनिक भागों, विद्युत आवास, कंटेनर और संचार उपकरण",
        "focus": "PC पर आधारित स्थैतिक विघटनकारी सामग्री, एक लौ-मंदक निर्माण दिशा के साथ कार्बन-फाइबर प्रबलित तकनीक का उपयोग करना। अनुप्रयोग दिशाओं में बोर्ड, चादरें, वाहक टेप, प्रोफाइल, चिमटी, इलेक्ट्रॉनिक भागों, विद्युत आवास, कंटेनर और संचार उपकरण शामिल हैं; ग्रेड और तैयार भाग के लिए प्रतिरोध और प्रसंस्करण की स्थिति को मान्य करें।",
        "process": "ग्रेड के लिए सुखाने, पिघलने के तापमान, मोल्ड तापमान और निवास के समय की पुष्टि करें; परीक्षणों के बाद प्रतिरोध, उपस्थिति और आयामों की जाँच करें।",
        "reinforcement": "कार्बन-फाइबर प्रबलित; ग्रेड के लिए सुदृढीकरण सामग्री और निर्माण की पुष्टि करें",
        "tests": [
          "प्रतिरोध: इलेक्ट्रोड, परीक्षण वोल्टेज, नमूना स्थिति, तापमान और आर्द्रता को परिभाषित करें; सामग्री के नमूनों और ढाले हुए भागों दोनों का परीक्षण करें",
          "दीर्घकालिक व्यवहार: कंडीशनिंग, सफाई, घर्षण और उम्र बढ़ने के बाद स्थैतिक नियंत्रण का मूल्यांकन करें",
          "भाग सत्यापन: इच्छित अनुप्रयोग में दीवार की मोटाई, फाइबर अभिविन्यास, असेंबली और ग्राउंडिंग का आकलन करें"
        ]
      },
